from typing import List

def countOfNodes(n: int, graph: List[List[int]]) -> int:
    def bfs_distance(graph, start):
        queue = [start]
        distances = [-1] * (n + 1)
        distances[start] = 0
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if distances[neighbor] == -1:
                    distances[neighbor] = distances[node] + 1
                    queue.append(neighbor)
        return distances

    even_distance_pairs = 0
    for i in range(1, n + 1):
        distances = bfs_distance(graph, i)
        even_distance_pairs += sum(1 for d in distances if d != -1 and d % 2 == 0)

    return even_distance_pairs // 2
